"""Retained native receipt audit plus exact owner bridge replays; no Cargo or native acquisition."""
import hashlib,json,pathlib,sys,subprocess
from datetime import datetime,timezone
ROOT=pathlib.Path('/Users/erik/.codex/worktrees/1598/umf')
SELF=pathlib.Path('/private/tmp/original-cell-bridge-astra-review.py')
assert pathlib.Path.cwd()==ROOT and pathlib.Path(__file__).resolve()==SELF and len(sys.argv)==1
OWNER=pathlib.Path('/Users/erik/Projects/weft')
TOOL=pathlib.Path('/private/tmp/weft-toolchain/rustup/toolchains/1.90.0-aarch64-apple-darwin/bin')
BINARY=pathlib.Path('/private/tmp/umf-security-weft-bridge-target/debug/examples/security_cell_inspection')
RECEIPT=ROOT/'docs/helix/04-build/evidence/security/truss-original-use.json'
PROBE=ROOT/'tools/security/truss-original-use-probe.py'
paths=[SELF,RECEIPT,PROBE,BINARY,OWNER/'crates/weft-core/examples/security_cell_inspection.rs',OWNER/'crates/weft-core/src/security_result_cells.rs',OWNER/'crates/weft-core/src/security_result_check.rs',OWNER/'crates/weft-core/src/json.rs',OWNER/'crates/weft-core/src/compile.rs']
frozen={str(p):p.read_bytes() for p in paths}
sha=lambda b:hashlib.sha256(b).hexdigest()
def file_hash(path):
 h=hashlib.sha256()
 with pathlib.Path(path).open('rb') as f:
  for chunk in iter(lambda:f.read(1024*1024),b''):h.update(chunk)
 return h.hexdigest()
r=json.loads(frozen[str(RECEIPT)])
assert r['status']=='passed' and r['engine']['number']=='170009'
observations=r['observations'];assert len(observations)==545
obs={o['id']:o for o in observations};assert len(obs)==len(observations)
assert all(o['expected']==o['observed'] for o in observations)
stale=[p for p,h in r['sourceDigests'].items() if file_hash(p)!=h];assert not stale
build=r['cellInspectionBuild']
command=[str(TOOL/'cargo'),'build','--offline','--locked','-p','weft-core','--example','security_cell_inspection','--target-dir','/private/tmp/umf-security-weft-bridge-target']
assert build['command']==command and build['exitCode']==0 and build['sourcesUnchanged'] is True
configs=[OWNER/'.cargo/config',OWNER/'.cargo/config.toml',pathlib.Path('/private/tmp/weft-toolchain/cargo/config'),pathlib.Path('/private/tmp/weft-toolchain/cargo/config.toml')]
selected=[OWNER/'Cargo.toml',OWNER/'Cargo.lock',PROBE]
for base in [OWNER/'crates',OWNER/'vendor',OWNER/'spec',OWNER/'docs/helix/03-test/fixtures']:
 selected.extend(p for p in base.rglob('*') if p.is_file() and 'target' not in p.parts)
for base in [TOOL,TOOL.parent/'lib']:
 selected.extend(p for p in base.rglob('*') if p.is_file())
selected.extend(p for p in configs if p.is_file())
assert set(build['sourceDigests'])=={str(p) for p in selected}
assert build['configPresence']=={str(p):p.exists() for p in configs}
assert all(r['sourceDigests'][p]==h for p,h in build['sourceDigests'].items())
assert '/private/tmp/umf-security-weft-bridge-target/debug/examples/security_cell_inspection' not in build['sourceDigests']
expected={'predicate':[['RAB']],'predicate-empty':[],'order':[['RA'],['RAB']],'order-empty':[],'join':[['RA'],['RAB']],'join-empty':[]}
captures=r['cellCorrespondence'];assert len(captures)==6 and {c['id'] for c in captures}==set(expected)
programs={p['id']:p for p in r['programs']}
identity={'documentId':'domain','revision':'schema-natural-1','module':'m','element':'resourceId'}
contract={'version':'weft.security.result-contract/0.1.0','encoding':'weft.security.cells/0.1.0','columns':[{'position':1,'outputName':'resourceId','sourceFields':[identity],'outcomes':[{'disposition':'original','id':'original','domain':{'kind':'model','field':identity}}]}]}
contract_hash=sha(json.dumps(contract,separators=(',',':')).encode())
reviewed=[]
replays=[]
def replay(label,packet,report=None):
 assert file_hash(BINARY)==r['sourceDigests'][str(BINARY)]
 request=json.dumps(packet).encode('utf-8')
 actual=subprocess.run([str(BINARY)],input=request,capture_output=True,timeout=15)
 if report is not None:
  assert actual.returncode==0 and actual.stderr==b'' and json.loads(actual.stdout)==report
 else:
  assert actual.returncode==1 and actual.stdout==b'' and json.loads(actual.stderr)=={'code':'WFT-SECURITY-CELL-INSPECTION','severity':'error','message':'Cell inspection refused','phase':'input'}
 assert file_hash(BINARY)==r['sourceDigests'][str(BINARY)]
 replays.append({'id':label,'argv':[str(BINARY)],'input':packet,'inputSha256':sha(request),'exitCode':actual.returncode,'stdout':actual.stdout.decode('utf-8'),'stderr':actual.stderr.decode('utf-8')})
for c in captures:
 label=c['id'];raw=bytes.fromhex(c['nativeRowsHex']);assert raw.hex()==c['nativeRowsHex'] and raw.endswith(b'\n')
 text=raw.decode('utf-8',errors='strict');assert json.loads(text)==expected[label]
 digest=sha(raw);assert digest==c['nativeRowsSha256']
 assert c['actor']=='umf_sec_alice' and c['nativeSql']=='SELECT security_raw.query_'+label.replace('-','_')+'()'
 observed=obs[label+':cell-native-capture-correspondence'];assert observed['expected']==expected[label] and observed['observed']==expected[label]
 p=programs[label]['artifact'];source=p['request']
 request={'interfaceVersion':'weft-compile/0.4.0','dialect':'weft-sql/0.2.0','sql':source['sql'],'modules':source['modules'],'parameters':source['parameters'],'security':{'version':'umf.security/0.1.0',**{k:source[k] for k in ['policyJson','ontologyJson','queryProfileJson']}},'target':{**{k:source[k] for k in ['backendId','backendVersion','targetProfile','bindingJson']},'bindingSha256':sha(source['bindingJson'].encode())}}
 if source['readProfile'] is not None:request['readProfile']=source['readProfile']
 assert c['compileRequest']==request
 assert p['handoff']['applicationPlan']['outputs']==[{'expression':{'identity':identity,'op':'field','scan':'s0'},'name':'resourceId'}]
 report={'status':'correspondence-only','rowCount':len(expected[label]),'columnCount':1,'nativeRowsSha256':digest,'resultContractSha256':contract_hash,'releasedRows':0}
 assert c['report']==report
 packet={'version':'weft.security.cell-inspection/0.1.0','compileRequestJson':json.dumps(request),'nativeRowsJson':text}
 replay(label+':positive',packet,report)
 assert len(c['controls'])==3 and {x['id'] for x in c['controls']}=={'null','wrong-width','positional-array'}
 for control in c['controls']:
  assert control['exitCode']==1 and control['diagnostic']=={'code':'WFT-SECURITY-CELL-INSPECTION','severity':'error','message':'Cell inspection refused','phase':'input'}
  mutant=[packet[k] for k in ['version','compileRequestJson','nativeRowsJson']] if control['id']=='positional-array' else {**packet,'nativeRowsJson':json.dumps([[None]] if control['id']=='null' else [['RA','extra']])}
  replay(label+':'+control['id']+'-refusal',mutant)
  o=obs[label+':cell-'+control['id']+'-refusal'];assert o['expected']=={'refused':True,'code':'WFT-SECURITY-CELL-INSPECTION','phase':'input'}
 reviewed.append({'id':label,'rows':len(expected[label]),'nativeBytesSha256':digest,'retainedTrailingLf':True,'originalRequestAndOutputMatched':True,'independentlyAuthoredContractSha256':contract_hash,'exactNullWidthAndPositionalArrayRefusals':True})
assert len(replays)==24 and sum(x['exitCode']==0 for x in replays)==6
assert build['configPresence']=={str(p):p.exists() for p in configs}
current_selected=[OWNER/'Cargo.toml',OWNER/'Cargo.lock',PROBE]
for base in [OWNER/'crates',OWNER/'vendor',OWNER/'spec',OWNER/'docs/helix/03-test/fixtures']:
 current_selected.extend(p for p in base.rglob('*') if p.is_file() and 'target' not in p.parts)
for base in [TOOL,TOOL.parent/'lib']:
 current_selected.extend(p for p in base.rglob('*') if p.is_file())
current_selected.extend(p for p in configs if p.is_file())
assert set(build['sourceDigests'])=={str(p) for p in current_selected}
assert all(pathlib.Path(p).read_bytes()==b for p,b in frozen.items())
assert all(file_hash(p)==h for p,h in r['sourceDigests'].items())
result={'id':'original-cell-bridge-astra-review','status':'clean-within-qualified-inspection-scope','reviewer':'/root/astra_security_review','generatedAt':datetime.now(timezone.utc).isoformat(),'sourceDigests':{p:sha(b) for p,b in frozen.items()},'sourcesUnchanged':True,'reviewCommand':{'argv':[sys.executable,str(SELF)],'sourceSha256':sha(frozen[str(SELF)]),'source':frozen[str(SELF)].decode()},'nativeExecution':'Parent-executed PostgreSQL fixture receipt; reviewer audited retained bytes/observations and did not duplicate native execution.','nativeReceiptAudit':{'observations':545,'uniqueIds':545,'allMatch':True,'sourcePins':len(r['sourceDigests']),'stale':stale,'selectedBuildInputPins':len(build['sourceDigests']),'configPresenceMatched':True},'captures':reviewed,'independentOwnerReplays':{'positive':6,'refusals':18,'executions':replays},'sourceReview':['Selected existing build-input hashes are frozen before Cargo, with exact path-set/config-presence and byte rechecks afterward, before native acquisition and before receipt publication; produced binary is captured as output.','Original psql stdout is retained as binary bytes including LF, decoded strictly once and transferred as an exact JSON string; the fresh owner executable reports the same hash.','The owner example explicitly requires an object before closed struct decoding, invokes the actual compiler factory only after admission, constructs direct Original string cells and calls the actual checker. It returns counts/hashes only and requires the public compiler to remain blocked with BACKEND-REQUIRED.','Null/wrong-width controls test the example string-row encoding boundary; positional-array controls independently require the outer input object carrier. These do not establish general runtime absence or physical codec support.'],'scope':'Independently replayed the six retained exact bridge inputs and 18 reconstructed null/width/positional controls against the already built pinned owner binary, without Cargo or native acquisition. Six fixed raw-fixture predicate/order/join string-result captures, including empty variants, and their pure owner-context cell inspection. Cargo registry/dependency artifact cache, platform linker/SDK and process environment remain trusted premises; selected input pinning is not a hermetic-build or compiler-refinement proof. No runtime policy-selection, current-authority release, public activation or broader backend acceptance is established.','nativeImplementationQualified':False,'acceptanceCasesPromoted':[]}
out=ROOT/'docs/helix/04-build/evidence/security/original-cell-bridge-astra-review.json'
if out.exists():
 old=out.read_bytes();archive=out.with_name('original-cell-bridge-astra-review-prior-'+sha(old)[:16]+'.json')
 if archive.exists():assert archive.read_bytes()==old
 else:archive.write_bytes(old)
 result['previousReceipt']={'path':str(archive),'sha256':sha(old),'scope':'Historical only.'}
out.write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({'status':result['status'],'observations':545,'captures':len(reviewed),'positiveReplays':6,'refusalReplays':18,'pins':len(r['sourceDigests']),'buildPins':len(build['sourceDigests']),'output':str(out)}))
